// This file is generated by AI.

// 实时预览行号指示器的渲染断言。
//
// 两个曾经踩过的坑, 在这里钉住:
//
// 1. **自动换行时不能每折一行多画一个箭头**。图标走的是零长度区间 —— 一旦有人图省事
//    把它改成整行区间 (`isWholeLine`), Monaco 会把字形栏图标铺到折出来的每一个视觉行上,
//    一条长语句旁边就多出一串箭头。
// 2. 图标与整行高亮必须是**两条装饰**: 图标只占第一行的第一个字符, 高亮才是整行。
//
// 这里用结构化替身而不是真 Monaco: 控制器只用到少数几个成员, 直接把它们记下来断言
// 比拉起整个编辑器便宜得多, 也不会因为 Monaco 版本变化而假失败。

import { describe, expect, it, vi } from 'vitest';

import { createLivePreviewGutterController } from '../src/editor/gutter-live-preview';
import type { LivePreviewMarker } from '../src/preview/live-preview';

interface RecordedDecoration {
  range: { startLineNumber: number; startColumn: number; endLineNumber: number; endColumn: number };
  options: {
    glyphMarginClassName?: string | null;
    glyphMarginHoverMessage?: { value: string };
    className?: string;
    isWholeLine?: boolean;
  };
}

/** 造一个"只有一行折成多行"的假编辑器: 行内容长度足够长, 折行是编辑器的事, 不影响行号 */
function createFakeEditor(lineCount = 10, lineLength = 200) {
  let recorded: RecordedDecoration[] = [];
  const mouseListeners: Array<(event: unknown) => void> = [];

  const editor = {
    createDecorationsCollection: () => ({
      get length() {
        return recorded.length;
      },
      set: (decorations: RecordedDecoration[]) => {
        recorded = [...decorations];
        return [];
      },
      clear: () => {
        recorded = [];
      },
    }),
    getModel: () => ({
      getLineCount: () => lineCount,
      getLineMaxColumn: () => lineLength + 1,
    }),
    onMouseDown: (listener: (event: unknown) => void) => {
      mouseListeners.push(listener);
      return { dispose: () => {} };
    },
    onDidChangeModelContent: () => ({ dispose: () => {} }),
  };

  return {
    editor: editor as unknown as Parameters<typeof createLivePreviewGutterController>[0]['editor'],
    decorations: () => recorded,
    emitMouseDown: (event: unknown) => mouseListeners.forEach((listener) => listener(event)),
  };
}

function marker(overrides: Partial<LivePreviewMarker> = {}): LivePreviewMarker {
  return {
    docPath: 'C:\\project\\game\\scene\\start.txt',
    line: 5,
    phase: 'executing',
    sceneName: 'start.txt',
    ...overrides,
  };
}

function setup(current: LivePreviewMarker | null, ready = true) {
  const fake = createFakeEditor();
  const onReplay = vi.fn();
  const controller = createLivePreviewGutterController({
    editor: fake.editor,
    getMarker: () => current,
    isReplayAvailable: () => ready,
    onReplay,
  });
  controller.sync();
  return { ...fake, controller, onReplay };
}

describe('实时预览指示器的装饰', () => {
  it('图标与高亮是两条装饰, 图标只占第一行的第一个字符', () => {
    const { decorations } = setup(marker());
    const list = decorations();
    expect(list).toHaveLength(2);

    const [glyph, highlight] = list;
    // 零长度区间 => Monaco 只在未折行的第一视觉行画一次图标
    expect(glyph.range).toEqual({ startLineNumber: 5, startColumn: 1, endLineNumber: 5, endColumn: 1 });
    expect(glyph.options.glyphMarginClassName).toContain('editor-block-glyph');
    expect(glyph.options.glyphMarginClassName).toContain('live-preview-glyph-executing');

    // 高亮是整行, 且**不带**字形栏类名 —— 两者混在一条装饰上就会回到"每折一行一个箭头"
    expect(highlight.options.isWholeLine).toBe(true);
    expect(highlight.options.className).toBe('live-preview-line-executing');
    expect(highlight.options.glyphMarginClassName).toBeUndefined();
  });

  it('图标装饰永远不是整行装饰', () => {
    for (const phase of ['executing', 'done', 'passed', 'failed'] as const) {
      const [glyph] = setup(marker({ phase })).decorations();
      expect(glyph.options.isWholeLine).toBeUndefined();
      expect(glyph.range.startColumn).toBe(1);
      expect(glyph.range.endColumn).toBe(1);
      expect(glyph.range.endLineNumber).toBe(glyph.range.startLineNumber);
    }
  });

  it('四种状态各有自己的图标类与配色类', () => {
    const seen = new Set<string>();
    for (const phase of ['executing', 'done', 'passed', 'failed'] as const) {
      const [glyph, highlight] = setup(marker({ phase })).decorations();
      seen.add(glyph.options.glyphMarginClassName ?? '');
      expect(highlight.options.className).toBe(`live-preview-line-${phase}`);
    }
    expect(seen.size).toBe(4);
  });

  it('没有指示器时不留任何装饰', () => {
    expect(setup(null).decorations()).toHaveLength(0);
  });

  it('行号超出文档时夹到末行, 不留悬空装饰', () => {
    const [glyph, highlight] = setup(marker({ line: 999 })).decorations();
    expect(glyph.range.startLineNumber).toBe(10);
    expect(highlight.range.endLineNumber).toBe(10);
  });
});

describe('指示器的点击重跑', () => {
  function mouseEvent(className: string, lineNumber = 5) {
    return {
      event: { leftButton: true },
      target: {
        element: { classList: { contains: (name: string) => name === className } },
        position: { lineNumber },
      },
    };
  }

  it('点"已越过"的箭头会重跑那一行', () => {
    const { emitMouseDown, onReplay } = setup(marker({ phase: 'passed' }));
    emitMouseDown(mouseEvent('editor-block-glyph', 7));
    expect(onReplay).toHaveBeenCalledWith(7);
  });

  it('点"未能执行"的箭头会重跑那一行', () => {
    const { emitMouseDown, onReplay } = setup(marker({ phase: 'failed' }));
    emitMouseDown(mouseEvent('editor-block-glyph'));
    expect(onReplay).toHaveBeenCalledWith(5);
  });

  it('还在等待时点它不重跑 (重复同步只会打断正在进行的那次)', () => {
    const { emitMouseDown, onReplay } = setup(marker({ phase: 'executing' }));
    emitMouseDown(mouseEvent('editor-block-glyph'));
    expect(onReplay).not.toHaveBeenCalled();
  });

  it('预览未连接时点它不重跑', () => {
    const { emitMouseDown, onReplay } = setup(marker({ phase: 'failed' }), false);
    emitMouseDown(mouseEvent('editor-block-glyph'));
    expect(onReplay).not.toHaveBeenCalled();
  });

  it('点别处 (不是我们的图标) 不重跑', () => {
    const { emitMouseDown, onReplay } = setup(marker({ phase: 'failed' }));
    emitMouseDown(mouseEvent('git-gutter-added'));
    expect(onReplay).not.toHaveBeenCalled();
  });
});
